#!/usr/bin/env node
// Checks src/lib/ieee754.mjs (used by the interactive IEEE 754 lab) against the JVM's own answers in
// java-track/examples/src/test/resources/fixtures/float-lab.tsv (generated by FloatLabFixtureTest).
import fs from 'node:fs';
import path from 'node:path';
import { JAVA_TRACK_ROOT } from '../src/lib/curriculum-core.mjs';
import { bitsOf, valueOf, parseJava, javaToString, exactString, decompose, ulp, errorOf } from '../src/lib/ieee754.mjs';

const fixture = path.join(JAVA_TRACK_ROOT, 'examples/src/test/resources/fixtures/float-lab.tsv');
const rows = fs.readFileSync(fixture, 'utf8').split('\n').filter((l) => l && !l.startsWith('#'));
const failures = [];
for (const row of rows) {
	const [format, input, hex, toString, exact, kind, ulpText] = row.split('\t');
	const value = parseJava(input, format);
	const bits = bitsOf(value, format);
	const actual = {
		bits: bits.toString(16),
		toString: javaToString(value, format),
		exact: exactString(bits, format),
		kind: decompose(bits, format).kind,
		ulp: javaToString(ulp(value, format), format),
	};
	const expected = { bits: hex, toString, exact, kind, ulp: ulpText };
	for (const key of Object.keys(expected)) {
		if (actual[key] !== expected[key]) {
			failures.push(`${format} ${input} ${key}: expected ${expected[key].slice(0, 80)}, got ${actual[key].slice(0, 80)}`);
		}
	}
}
// Random bit patterns (anything a learner can click together): printing and re-parsing must match Java.
const randomFixture = path.join(JAVA_TRACK_ROOT, 'examples/src/test/resources/fixtures/float-lab-random.tsv');
const randomRows = fs.readFileSync(randomFixture, 'utf8').split('\n').filter((l) => l && !l.startsWith('#'));
for (const row of randomRows) {
	const [format, hex, toString, ulpText] = row.split('\t');
	const bits = BigInt(`0x${hex}`);
	const value = valueOf(bits, format);
	const printed = javaToString(value, format);
	if (printed !== toString) failures.push(`${format} ${hex} toString: expected ${toString}, got ${printed}`);
	const gap = javaToString(ulp(value, format), format);
	if (gap !== ulpText) failures.push(`${format} ${hex} ulp: expected ${ulpText}, got ${gap}`);
	const reparsed = bitsOf(parseJava(toString, format), format);
	if (reparsed !== bits) failures.push(`${format} ${hex} parse(${toString}) gave ${reparsed.toString(16)}`);
}

// The error readout (typed − stored), formatted from exact digits. Expected values computed on the JVM:
// new BigDecimal(text).subtract(new BigDecimal(x)).round(new MathContext(3)), shown with 3 significant digits
for (const [text, format, expected] of [
	['0.7', 'float', '1.19e-8'],
	['0.1', 'double', '-5.55e-18'],
	['16777217', 'float', '1.00'],
	['4.125', 'float', '0'],
	['5e-324', 'double', '5.93e-326'],
	['1e-45', 'float', '-4.01e-46'],
]) {
	const actual = errorOf(text, bitsOf(parseJava(text, format), format), format);
	if (actual !== expected) failures.push(`errorOf(${text}, ${format}): expected ${expected}, got ${actual}`);
}

if (failures.length) {
	console.error(failures.join('\n'));
	console.error(`FAILED: ${failures.length} mismatches against the JVM fixture`);
	process.exit(1);
}
console.log(`OK: IEEE 754 lab agrees with the JVM on ${rows.length} fixture rows and ${randomRows.length} random bit patterns`);
